<?php
require_once __DIR__ . '/includes/auth.php'; require_auth();
$pageTitle='Asset library'; $pageSubtitle='Browse, search and organize your digital assets'; $u=current_user();
$pageActions=in_array($u['role_name'],['Administrator','Asset Manager'],true)?'<a class="btn btn-primary" href="'.e(url('upload.php')).'"><i class="bi bi-plus-lg me-1"></i>Upload</a>':'';
$q=page_param('q');$category=page_param('category');$type=page_param('type');$status=page_param('status','active');$uploader=page_param('uploader');$dateFrom=page_param('date_from');$dateTo=page_param('date_to');$minSize=page_param('min_size');$maxSize=page_param('max_size');$tag=page_param('tag');$view=in_array(page_param('view','grid'),['grid','list'],true)?page_param('view','grid'):'grid';
$sorts=['newest'=>'a.created_at DESC','oldest'=>'a.created_at ASC','name_az'=>'a.title ASC','name_za'=>'a.title DESC','largest'=>'a.file_size DESC','smallest'=>'a.file_size ASC','downloads'=>'a.download_count DESC'];$sort=page_param('sort','newest');$order=$sorts[$sort]??$sorts['newest'];
$where=['a.deleted_at IS NULL'];$params=[];
if($u['role_name']!=='Administrator'){$uid=(int)$u['id'];$where[]="(a.visibility IN ('organization','public') OR a.uploaded_by={$uid} OR EXISTS(SELECT 1 FROM collection_assets ca4 JOIN collections c4 ON c4.id=ca4.collection_id LEFT JOIN collection_shares cs4 ON cs4.collection_id=c4.id AND cs4.user_id={$uid} WHERE ca4.asset_id=a.id AND (c4.owner_id={$uid} OR c4.visibility='organization' OR cs4.user_id IS NOT NULL)))";}
if($q!==''){$where[]='(a.title LIKE ? OR a.original_filename LIKE ? OR a.description LIKE ? OR c.name LIKE ? OR u.name LIKE ? OR EXISTS(SELECT 1 FROM asset_tags at2 JOIN tags t2 ON t2.id=at2.tag_id WHERE at2.asset_id=a.id AND t2.name LIKE ?))';for($i=0;$i<6;$i++)$params[]='%'.$q.'%';}
if($category!==''){$where[]='a.category_id=?';$params[]=(int)$category;}if($type!==''){$where[]='a.file_extension=?';$params[]=$type;}if(in_array($status,['active','archived'],true)){$where[]='a.status=?';$params[]=$status;}if($uploader!==''){$where[]='a.uploaded_by=?';$params[]=(int)$uploader;}if($dateFrom!==''){$where[]='DATE(a.created_at)>=?';$params[]=$dateFrom;}if($dateTo!==''){$where[]='DATE(a.created_at)<=?';$params[]=$dateTo;}if($minSize!==''){$where[]='a.file_size>=?';$params[]=(int)$minSize*1024*1024;}if($maxSize!==''){$where[]='a.file_size<=?';$params[]=(int)$maxSize*1024*1024;}if($tag!==''){$where[]='EXISTS(SELECT 1 FROM asset_tags at3 JOIN tags t3 ON t3.id=at3.tag_id WHERE at3.asset_id=a.id AND t3.name=?)';$params[]=$tag;}
$whereSql=implode(' AND ',$where);$count=db()->prepare("SELECT COUNT(*) FROM assets a LEFT JOIN categories c ON c.id=a.category_id JOIN users u ON u.id=a.uploaded_by WHERE $whereSql");$count->execute($params);$total=(int)$count->fetchColumn();$per=max(6,min(100,(int)setting('assets_per_page',24)));$pages=max(1,(int)ceil($total/$per));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*$per;
$stmt=db()->prepare("SELECT a.*,c.name category_name,u.name uploader_name,EXISTS(SELECT 1 FROM favorites f WHERE f.asset_id=a.id AND f.user_id=?) is_favorite FROM assets a LEFT JOIN categories c ON c.id=a.category_id JOIN users u ON u.id=a.uploaded_by WHERE $whereSql ORDER BY $order LIMIT $per OFFSET $offset");$stmt->execute(array_merge([$u['id']],$params));$assets=$stmt->fetchAll();
$categories=db()->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$users=db()->query("SELECT id,name FROM users WHERE status='active' AND deleted_at IS NULL ORDER BY name")->fetchAll();
require __DIR__.'/includes/header.php';
function query_with(array $changes):string{$params=array_merge($_GET,$changes);foreach($params as $k=>$v)if($v===''||$v===null)unset($params[$k]);return '?'.http_build_query($params);}
?>
<div class="card mb-4"><div class="card-body"><form method="get"><div class="row g-2 align-items-end"><div class="col-lg-4"><label class="form-label small">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Name, description, tag or uploader"></div><div class="col-sm-6 col-lg-2"><label class="form-label small">Category</label><select class="form-select" name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$category==(string)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-sm-6 col-lg-2"><label class="form-label small">File type</label><select class="form-select" name="type"><option value="">All types</option><?php foreach(allowed_extensions() as $ext):?><option <?=$type===$ext?'selected':''?>><?=e($ext)?></option><?php endforeach;?></select></div><div class="col-sm-6 col-lg-2"><label class="form-label small">Sort</label><select class="form-select" name="sort"><?php foreach(['newest'=>'Newest','oldest'=>'Oldest','name_az'=>'Name A–Z','name_za'=>'Name Z–A','largest'=>'Largest','smallest'=>'Smallest','downloads'=>'Most downloaded'] as $key=>$label):?><option value="<?=e($key)?>" <?=$sort===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div class="col-sm-6 col-lg-2"><button class="btn btn-primary w-100"><i class="bi bi-search me-1"></i>Apply</button></div></div>
<details class="mt-3"><summary class="small text-primary">Advanced filters</summary><div class="row g-2 pt-3"><div class="col-md-2"><label class="form-label small">Status</label><select name="status" class="form-select"><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="archived" <?=$status==='archived'?'selected':''?>>Archived</option><option value="" <?=$status===''?'selected':''?>>Any</option></select></div><?php if($users):?><div class="col-md-2"><label class="form-label small">Uploaded by</label><select name="uploader" class="form-select"><option value="">Anyone</option><?php foreach($users as $row):?><option value="<?=$row['id']?>" <?=$uploader==(string)$row['id']?'selected':''?>><?=e($row['name'])?></option><?php endforeach;?></select></div><?php endif;?><div class="col-md-2"><label class="form-label small">From date</label><input type="date" class="form-control" name="date_from" value="<?=e($dateFrom)?>"></div><div class="col-md-2"><label class="form-label small">To date</label><input type="date" class="form-control" name="date_to" value="<?=e($dateTo)?>"></div><div class="col-md-2"><label class="form-label small">Min size (MB)</label><input type="number" min="0" class="form-control" name="min_size" value="<?=e($minSize)?>"></div><div class="col-md-2"><label class="form-label small">Max size (MB)</label><input type="number" min="0" class="form-control" name="max_size" value="<?=e($maxSize)?>"></div></div></details></form></div></div>
<div class="d-flex justify-content-between align-items-center mb-3"><div class="text-muted small"><?=number_format($total)?> asset<?= $total===1?'':'s' ?></div><div class="btn-group"><a class="btn btn-sm <?=$view==='grid'?'btn-primary':'btn-outline-secondary'?>" href="<?=e(query_with(['view'=>'grid']))?>"><i class="bi bi-grid"></i></a><a class="btn btn-sm <?=$view==='list'?'btn-primary':'btn-outline-secondary'?>" href="<?=e(query_with(['view'=>'list']))?>"><i class="bi bi-list-ul"></i></a></div></div>
<?php if(!$assets):?><div class="card"><div class="empty-state"><i class="bi bi-folder2-open"></i><h2 class="h5 mt-3">No assets found</h2><p>Try changing your search or filters.</p></div></div><?php elseif($view==='grid'):?><div class="row g-4"><?php foreach($assets as $a):?><div class="col-sm-6 col-xl-4 col-xxl-3"><div class="card asset-card h-100"><a class="asset-thumb text-decoration-none" href="<?=e(url('asset-details.php?id='.$a['id']))?>"><?php if(in_array($a['file_extension'],['jpg','jpeg','png','gif','webp'],true)):?><img loading="lazy" src="<?=e(url('preview.php?id='.$a['id']))?>" alt="<?=e($a['title'])?>"><?php else:?><i class="bi <?=e(asset_icon($a['file_extension']))?>"></i><?php endif;?></a><div class="card-body"><div class="d-flex gap-2"><div class="flex-grow-1 overflow-hidden"><a class="fw-semibold text-dark text-decoration-none d-block text-truncate" href="<?=e(url('asset-details.php?id='.$a['id']))?>"><?=e($a['title'])?></a><small class="text-muted text-uppercase"><?=e($a['file_extension'])?> · <?=e(human_file_size((int)$a['file_size']))?></small></div><?php if($a['is_favorite']):?><i class="bi bi-star-fill text-warning"></i><?php endif;?></div><div class="mt-3 d-flex justify-content-between small"><span class="badge badge-soft"><?=e($a['category_name']??'Uncategorized')?></span><span class="text-muted"><?=e(date('M j, Y',strtotime($a['created_at'])))?></span></div></div></div></div><?php endforeach;?></div><?php else:?><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Asset</th><th>Category</th><th>Type</th><th>Size</th><th>Uploaded by</th><th>Date</th><th>Downloads</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($assets as $a):?><tr><td><a class="text-decoration-none fw-semibold" href="<?=e(url('asset-details.php?id='.$a['id']))?>"><i class="bi <?=e(asset_icon($a['file_extension']))?> text-primary me-2"></i><?=e($a['title'])?></a><small class="d-block text-muted ms-4 text-truncate" style="max-width:240px"><?=e($a['original_filename'])?></small></td><td><?=e($a['category_name']??'—')?></td><td class="text-uppercase"><?=e($a['file_extension'])?></td><td><?=e(human_file_size((int)$a['file_size']))?></td><td><?=e($a['uploader_name'])?></td><td><?=e(date('M j, Y',strtotime($a['created_at'])))?></td><td><?=number_format((int)$a['download_count'])?></td><td><span class="badge <?=$a['status']==='active'?'text-bg-success':'text-bg-secondary'?>"><?=e(ucfirst($a['status']))?></span></td><td><div class="dropdown"><button class="btn btn-sm btn-light" data-bs-toggle="dropdown"><i class="bi bi-three-dots"></i></button><ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item" href="<?=e(url('asset-details.php?id='.$a['id']))?>">Preview & details</a></li><li><a class="dropdown-item" href="<?=e(url('download.php?id='.$a['id']))?>">Download</a></li><?php if(asset_can_manage($a,$u)):?><li><a class="dropdown-item" href="<?=e(url('edit-asset.php?id='.$a['id']))?>">Edit</a></li><?php endif;?></ul></div></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?>
<?php if($pages>1):?><nav class="mt-4"><ul class="pagination justify-content-center"><li class="page-item <?=$page<=1?'disabled':''?>"><a class="page-link" href="<?=e(query_with(['page'=>$page-1]))?>">Previous</a></li><?php for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++):?><li class="page-item <?=$p===$page?'active':''?>"><a class="page-link" href="<?=e(query_with(['page'=>$p]))?>"><?=$p?></a></li><?php endfor;?><li class="page-item <?=$page>=$pages?'disabled':''?>"><a class="page-link" href="<?=e(query_with(['page'=>$page+1]))?>">Next</a></li></ul></nav><?php endif;?>
